From 2a8659b3dc64edf76d3f0dc331e694bb5c7fe361 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:03:15 +0100
Subject: [PATCH] connectiondetails: show IP addresses of active VPN
 connections

A VPN is never the active connection of a device, so the details only
saw it as inactive and showed nothing but its plugin. Find its own
active connection instead and take the IP configuration from there.

BUG: 516854
---
 libs/editor/connectiondetails.cpp | 56 +++++++++++++++++++++----------
 1 file changed, 39 insertions(+), 17 deletions(-)

diff --git a/libs/editor/connectiondetails.cpp b/libs/editor/connectiondetails.cpp
index d030b16d9..53d7d0502 100644
--- a/libs/editor/connectiondetails.cpp
+++ b/libs/editor/connectiondetails.cpp
@@ -68,6 +68,18 @@ getConnectionDetails(const NetworkManager::Connection::Ptr &connection, const Ne
         isConnectionActive = (activeConn->connection()->path() == connection->path());
     }

+    // A VPN is not the active connection of any device, so find its own active connection
+    bool isVpnActive = false;
+    if (!isConnectionActive && settings && settings->connectionType() == NetworkManager::ConnectionSettings::Vpn) {
+        for (const NetworkManager::ActiveConnection::Ptr &active : NetworkManager::activeConnections()) {
+            if (active->vpn() && active->connection() && active->connection()->path() == connection->path()) {
+                activeConn = active;
+                isVpnActive = true;
+                break;
+            }
+        }
+    }
+
     // Determine connection type from settings if available, otherwise from device type
     NetworkManager::ConnectionSettings::ConnectionType type = NetworkManager::ConnectionSettings::Unknown;
     if (settings) {
@@ -219,7 +231,7 @@ getConnectionDetails(const NetworkManager::Connection::Ptr &connection, const Ne
             details.append({i18n("VPN Plugin"), vpnType});
         }

-        if (isConnectionActive) {
+        if (isConnectionActive || isVpnActive) {
             NetworkManager::VpnConnection::Ptr vpnConnection;

             if (activeConn) {
@@ -321,24 +333,34 @@ getConnectionDetails(const NetworkManager::Connection::Ptr &connection, const Ne
         sections.append({i18n("General"), details});
     }

+    NetworkManager::IpConfig ipV4Config;
+    NetworkManager::IpConfig ipV6Config;
+    if (isVpnActive) {
+        ipV4Config = activeConn->ipV4Config();
+        ipV6Config = activeConn->ipV6Config();
+    } else if (device && isConnectionActive) {
+        ipV4Config = device->ipV4Config();
+        ipV6Config = device->ipV6Config();
+    }
+
     // Get IPv4 Address and related nameservers + IPv4 default gateway
-    if (device && device->ipV4Config().isValid() && isConnectionActive) {
+    if (ipV4Config.isValid()) {
         QList<QPair<QString, QString>> details;
-        if (!device->ipV4Config().addresses().isEmpty()) {
-            QHostAddress addr = device->ipV4Config().addresses().first().ip();
+        if (!ipV4Config.addresses().isEmpty()) {
+            QHostAddress addr = ipV4Config.addresses().first().ip();
             if (!addr.isNull() && addr.isGlobal()) {
                 details.append({i18n("IPv4 Address"), addr.toString()});
             }
         }
-        if (!device->ipV4Config().gateway().isEmpty()) {
-            QString addr = device->ipV4Config().gateway();
+        if (!ipV4Config.gateway().isEmpty()) {
+            QString addr = ipV4Config.gateway();
             if (!addr.isNull()) {
                 details.append({i18n("IPv4 Default Gateway"), addr});
             }
         }
-        if (!device->ipV4Config().nameservers().isEmpty()) {
-            QHostAddress addr1 = device->ipV4Config().nameservers().first();
-            QHostAddress addr2 = device->ipV4Config().nameservers().last();
+        if (!ipV4Config.nameservers().isEmpty()) {
+            QHostAddress addr1 = ipV4Config.nameservers().first();
+            QHostAddress addr2 = ipV4Config.nameservers().last();
             if (!addr1.isNull()) {
                 details.append({i18n("IPv4 Primary Nameserver"), addr1.toString()});
             }
@@ -354,25 +376,25 @@ getConnectionDetails(const NetworkManager::Connection::Ptr &connection, const Ne
     }

     // Get IPv6 Address and related nameservers + IPv6 default gateway
-    if (device && device->ipV6Config().isValid() && isConnectionActive) {
+    if (ipV6Config.isValid()) {
         QList<QPair<QString, QString>> details;
-        if (!device->ipV6Config().addresses().isEmpty()) {
-            QHostAddress addr = device->ipV6Config().addresses().first().ip();
+        if (!ipV6Config.addresses().isEmpty()) {
+            QHostAddress addr = ipV6Config.addresses().first().ip();
             if (!addr.isNull() && addr.isGlobal() && !addr.isUniqueLocalUnicast()) {
                 details.append({i18n("IPv6 Address"), addr.toString()});
             } else if (!addr.isNull() && addr.isGlobal() && addr.isUniqueLocalUnicast()) {
                 details.append({i18n("IPv6 ULA Address"), addr.toString()});
             }
         }
-        if (!device->ipV6Config().gateway().isEmpty()) {
-            QString addr = device->ipV6Config().gateway();
+        if (!ipV6Config.gateway().isEmpty()) {
+            QString addr = ipV6Config.gateway();
             if (!addr.isNull()) {
                 details.append({i18n("IPv6 Default Gateway"), addr});
             }
         }
-        if (!device->ipV6Config().nameservers().isEmpty()) {
-            QHostAddress addr1 = device->ipV6Config().nameservers().first();
-            QHostAddress addr2 = device->ipV6Config().nameservers().last();
+        if (!ipV6Config.nameservers().isEmpty()) {
+            QHostAddress addr1 = ipV6Config.nameservers().first();
+            QHostAddress addr2 = ipV6Config.nameservers().last();
             if (!addr1.isNull()) {
                 details.append({i18n("IPv6 Primary Nameserver"), addr1.toString()});
             }
-- 
